def count_sum_paths(parent, values, target):
    n = len(parent)
    children = [[] for _ in range(n)]
    root = 0
    for i, p in enumerate(parent):
        if p < 0:
            root = i
        else:
            children[p].append(i)
    seen = {0: 1}
    count = 0
    stack = [(root, 0, False)]
    while stack:
        node, total, leaving = stack.pop()
        if leaving:
            seen[total] -= 1
            continue
        total += values[node]
        count += seen.get(total - target, 0)
        seen[total] = seen.get(total, 0) + 1
        stack.append((node, total, True))
        for child in children[node]:
            stack.append((child, total, False))
    return count

